// step4_validate_instruction.js — SHARED instruction validator (step 4, written clean).
// Purpose: decide whether an owner custom instruction may activate, by checking it
// against tenant policies and the dialect_lexicon table. NOTHING here is hardcoded
// from one dialect: every danger word, negation marker, percent phrase, and number
// word comes from lexicon rows (all dialects present, active rows only).
//
// INPUT (single object):
//   { instruction_text, bound_key, bound_value, policies, lexicon }
//   - bound_key: one of max_discount_pct | max_installments | min_down_payment_pct
//     | booking_fee | cash_discount_pct, or null.
//   - bound_value: numeric, or null (bound_key + bound_value are all-or-nothing).
//   - policies: [{ key, value }] where value is a number OR {"value": number}.
//   - lexicon: [{ dialect, concept, term, term_value, is_active }] (DB rows).
// OUTPUT: { verdict: 'pass' } OR { verdict: 'reject', code, field, detail }.
//   Codes:
//     bound_exceeded         structured bound number violates its policy.
//     malformed_policy       the policy being checked has a non-numeric value
//                            (distinguished from a violating instruction).
//     use_structured_field   danger concept WITH a bound_key, written in free text
//                            (the number/policy detail rides in `detail`).
//     forbidden_action       danger concept WITHOUT a bound_key, written as an
//                            order (negotiation, diagnosis). No structured field
//                            exists for these, so "use structured field" would lie.
//     unknown_number_word    a percent marker with no resolvable number bound.
//     exception_requires_review  an exception marker (إلا/باستثناء/ماعدا) after the
//                            verb: exception beats negation, human must review.
//     invalid_bound          the instruction's own bound_value is not numeric
//                            (distinct from a malformed POLICY value).
//   SPEC-TENSION RESOLUTION (recorded, not hidden): the two-type model lists
//   negotiation among "dangerous, only via structured field", but no bound_key
//   exists for negotiation — so a negotiation order cannot be fixed by any
//   structured field. It is rejected as forbidden_action (the bot never negotiates
//   price itself), with that fact stated in `detail`.
//
// TEXT PIPELINE (in order, per spec):
//   1. custNorm: letter folding (أإآ→ا، ة→ه، ى→ي) + strip tatweel/diacritics in
//      [U+0640, U+064B–U+065F, U+0670]. The range EXCLUDES Eastern digits
//      (U+0660–U+0669) and ٪ (U+066A) — digits are folded, never deleted.
//   2. custLat: fold Eastern (U+0660–U+0669) and Persian (U+06F0–U+06F9) digits
//      to Latin digits.
//   3. Comma strip: /(\d)[,\u066c](?=\d{3})/g → '$1' (thousands separators only).
//   Terms from the lexicon are normalized by the SAME pipeline before matching.
//   (Consequence: MSA 'في المئة' normalizes to 'في الميه'; EGY 'في المية' stays.
//   Both match their own dialect's text, because both sides are normalized.)
//
// SENTENCES: split on . ؟ ! newline AND ؛ . Binding is sentence-local ONLY.
// DISTANCES are sentence-relative token offsets (i − sentence start), never a
// ±40-character window.
//
// NUMBER BINDING (spec wording, implemented literally): for each NUMBER in a
// sentence, its keyword is the nearest danger keyword BEFORE it, else the nearest
// danger keyword AFTER it. A danger keyword "owns" the numbers assigned to it.
// NUMBER-WORD CONVERSION: longest-match-first over lexicon number_word terms.
// Compounds (unit + و + tens, e.g. 'واحد وعشرين') resolve by longest match on the
// tens part plus the unit part; 'في المية' / percent phrases count as % markers.
// UNKNOWN-NUMBER-WORD RULE (defined here, before step 5): in a danger sentence,
// if a percent marker (٪ or any percent_phrase term) is present but NO number
// (digit, or lexicon number-word) can be bound to the danger keyword, the verdict
// is unknown_number_word. The detail names the token immediately before the
// percent marker when it is not a digit (e.g. 'زعبلوط' in 'خصم زعبلوط في المية'),
// else the sentence. This is fail-closed: an unresolvable number never passes.
// NEGATION (generalized to ANY forbidden word): a negation marker (lexicon
// concept=negation, all dialects) counts when EITHER (a) it is a standalone token
// within 2 words BEFORE the forbidden word in the same sentence, OR (b) it is
// ATTACHED: the token starts with a negation marker AND the remainder contains
// the forbidden term ('ماتتفاوضش' = ما + تتفاوض + ش; 'متتفاوضش' = م + تتفاوض + ش).
// Rule (b) requires the remainder to contain the term, so 'سلام' (contains 'لا'
// mid-word, not as a prefix) and 'مشغول'/'مشكلة' (remainder has no forbidden
// term) are NOT negation. A bare 'لا'/'ما' token with no forbidden word nearby
// changes nothing — negation only modifies a danger verdict, it never rejects
// or passes on its own.
// EXCEPTION BEATS NEGATION: إلا / باستثناء / ماعدا AFTER the verb in the same
// sentence → reject for review, even if a negation precedes the verb.
// FORBIDDEN-PHRASE MATCHING (validator side only): one-way containment — the
// text contains the phrase. Guard reply-phrase matching is a SEPARATE step-7
// decision and is NOT done here.
// 'مقدم' GUARD (documented trade-off): after normalization, 'مقدمة' becomes
// 'مقدمه'. A normalized 'مقدم' hit that forms exactly 'مقدمه' is treated as
// introduction and skipped. Cost: the possessive 'his down payment' reading of
// 'مقدمه' is missed; that phrasing is rare, 'المقدم' (with ال) still fires, and
// the structured bound_key path still covers real down-payment instructions.
// PRECEDENCE inside one free-text danger sentence: unknown_number_word first,
// then the danger rule (use_structured_field / forbidden_action). The structured
// bound path is checked before free text. First rejection wins.
// EMPTY instruction_text: vacuous pass (nothing dangerous in it).
// A malformed policy blocks ONLY when it is the policy being checked (same key);
// unrelated malformed policies do not block the verdict.

function normalizeArabic(s) {
  return String(s)
    .replace(/[أإآ]/g, 'ا')
    .replace(/ة/g, 'ه')
    .replace(/ى/g, 'ي')
    .replace(/[ـً-ٰٟ]/g, '');
}

function foldDigits(s) {
  return String(s).replace(/[٠-٩]/g, function (d) { return String(d.charCodeAt(0) - 0x660); })
    .replace(/[۰-۹]/g, function (d) { return String(d.charCodeAt(0) - 0x6f0); });
}

function stripThousands(s) {
  return String(s).replace(/(\d)[,٬](?=\d{3})/g, '$1');
}

function cleanText(s) {
  return stripThousands(foldDigits(normalizeArabic(s)));
}

function splitSentences(text) {
  return cleanText(text).split(/[.\؟!\n؛]+/).map(function (x) { return x.trim(); }).filter(Boolean);
}

function tokenize(sentence) {
  return sentence.split(/[\s،,؛:()«»"']+/).filter(Boolean);
}

function buildLexicon(rows) {
  var byConcept = {};
  (rows || []).filter(function (r) { return r && r.is_active !== false && r.term; }).forEach(function (r) {
    var term = cleanText(r.term);
    if (!term) return;
    byConcept[r.concept] = byConcept[r.concept] || [];
    byConcept[r.concept].push({ dialect: r.dialect, term: term, term_value: r.term_value });
  });
  Object.keys(byConcept).forEach(function (c) {
    byConcept[c].sort(function (a, b) { return b.term.length - a.term.length; });
  });
  return byConcept;
}

function unwrapPolicyValue(v) {
  if (v !== null && typeof v === 'object' && Object.prototype.hasOwnProperty.call(v, 'value')) return v.value;
  return v;
}

function policyNumber(policies, key) {
  var row = (policies || []).filter(function (p) { return p && p.key === key; })[0];
  if (!row) return { found: false };
  var v = unwrapPolicyValue(row.value);
  if (typeof v !== 'number' || isNaN(v)) return { found: true, malformed: true, raw: row.value };
  return { found: true, value: v };
}

// Concept → bound key (null = no structured field exists for this concept).
function conceptBoundKey(concept) {
  if (concept === 'discount') return 'max_discount_pct';
  if (concept === 'installment') return 'max_installments';
  if (concept === 'down_payment') return 'min_down_payment_pct';
  if (concept === 'fee') return 'booking_fee';
  return null;
}

function boundFails(key, instructionNumber, policyNumberValue) {
  if (key === 'max_discount_pct' || key === 'max_installments' || key === 'cash_discount_pct') {
    return instructionNumber > policyNumberValue;
  }
  if (key === 'min_down_payment_pct') return instructionNumber < policyNumberValue;
  if (key === 'booking_fee') return instructionNumber !== policyNumberValue;
  return false;
}

var DANGER_CONCEPTS = ['negotiate', 'discount', 'installment', 'down_payment', 'fee', 'diagnosis'];
var EXCEPTION_MARKERS = ['إلا', 'باستثناء', 'ماعدا'];

// Find danger-term hits in a sentence: [{ concept, term, tokenIdx, charIdx }].
// Substring containment per spec, with the مقدمه guard (see header).
function findDangerHits(sentence, lexicon) {
  var tokens = tokenize(sentence);
  var hits = [];
  var offset = 0;
  tokens.forEach(function (tok, ti) {
    var charIdx = sentence.indexOf(tok, offset);
    offset = charIdx + tok.length;
    DANGER_CONCEPTS.forEach(function (concept) {
      (lexicon[concept] || []).forEach(function (entry) {
        var t = entry.term;
        var pos = tok.indexOf(t);
        if (pos === -1) return;
        if (t === 'مقدم' && tok === 'مقدمه') return; // introduction, not down payment
        hits.push({ concept: concept, term: t, tokenIdx: ti, charIdx: charIdx + pos });
      });
    });
  });
  // One hit per (concept, token): keep the longest term per concept per token.
  var seen = {};
  return hits.filter(function (h) {
    var k = h.concept + '@' + h.tokenIdx;
    if (seen[k]) return false;
    seen[k] = true;
    return true;
  });
}

// Tokens covered by a percent phrase must NOT count as numbers: 'في المية'
// contains the number-word 'مية' (100). Without masking, 'خصم زعبلوط في المية'
// would bind 100 and never reach unknown_number_word. Returns a Set of token
// indices covered by any percent_phrase term (longest terms first).
function percentCoveredTokens(sentence, lexicon) {
  var tokens = tokenize(sentence);
  var covered = {};
  (lexicon['percent_phrase'] || []).forEach(function (e) {
    var words = e.term.split(/\s+/);
    if (words.length === 1) {
      tokens.forEach(function (t, ti) {
        // A token carrying BOTH a digit and the percent sign ('10٪') must NOT
        // be masked: the digit is a real number. Mask only digit-free tokens
        // (a standalone '٪' marker carries no number anyway).
        if (t.indexOf(words[0]) !== -1 && !/\d/.test(t)) covered[ti] = true;
      });
      return;
    }
    for (var i = 0; i + words.length <= tokens.length; i++) {
      var match = true;
      for (var j = 0; j < words.length; j++) {
        if (tokens[i + j] !== words[j]) { match = false; break; }
      }
      if (match) for (var k = 0; k < words.length; k++) covered[i + k] = true;
    }
  });
  return covered;
}

// Numbers in a sentence: digits (after cleaning) and lexicon number-words.
// Returns [{ value, tokenIdx, text, isWord }], longest-match-first for words.
// COMPOUNDS: unit + و + tens merge into one number ('واحد وعشرين' → 21,
// 'واحد و عشرين' → 21). Thousand/hundred compounds are NOT covered (spec).
// skipIdx: token indices to ignore (percent-phrase coverage, see above).
function findNumbers(sentence, lexicon, skipIdx) {
  var tokens = tokenize(sentence);
  var words = lexicon['number_word'] || [];
  function wordAt(tok) {
    var m = tok.match(/^\d+(\.\d+)?/);
    if (m) return { value: parseFloat(m[0]), text: m[0], isWord: false };
    for (var i = 0; i < words.length; i++) {
      if (tok === words[i].term || tok.indexOf(words[i].term) !== -1) {
        return { value: words[i].term_value, text: words[i].term, isWord: true };
      }
    }
    return null;
  }
  function isTens(v) { return v && v.isWord && [20, 30, 40, 50, 60, 70, 80, 90].indexOf(v.value) !== -1; }
  var out = [];
  for (var ti = 0; ti < tokens.length; ti++) {
    if (skipIdx && skipIdx[ti]) continue;
    var w = wordAt(tokens[ti]);
    if (!w) continue;
    if (w.isWord && w.value >= 1 && w.value <= 10) {
      // Try compound: next token 'و'+tens, or standalone 'و' + tens.
      var nx = tokens[ti + 1];
      var tens = null;
      if (nx && nx.charAt(0) === 'و') {
        var rest = nx.slice(1);
        var rw = wordAt(rest);
        if (isTens(rw)) tens = rw;
      }
      if (!tens && nx === 'و') {
        var rw2 = wordAt(tokens[ti + 2] || '');
        if (isTens(rw2)) tens = rw2;
      }
      if (tens) {
        out.push({ value: w.value + tens.value, tokenIdx: ti, text: w.text + '+' + tens.text, isWord: true });
        ti += (nx === 'و' ? 2 : 1);
        continue;
      }
    }
    out.push({ value: w.value, tokenIdx: ti, text: w.text, isWord: w.isWord });
  }
  return out;
}

function hasPercentMarker(sentence, lexicon) {
  if (sentence.indexOf('٪') !== -1 || sentence.indexOf('%') !== -1) return true;
  return (lexicon['percent_phrase'] || []).some(function (e) { return sentence.indexOf(e.term) !== -1; });
}

// Negation check for a danger hit at tokenIdx in this sentence's tokens.
// Returns 'negated' | 'exception' | null.
function negationStatus(tokens, tokenIdx, hitTerm, lexicon) {
  var markers = (lexicon['negation'] || []).map(function (e) { return e.term; });
  var excTerms = EXCEPTION_MARKERS.map(cleanText);
  // Exception AFTER the verb beats negation: check first.
  for (var j = tokenIdx + 1; j < tokens.length; j++) {
    if (excTerms.some(function (e) { return tokens[j].indexOf(e) !== -1; })) return 'exception';
  }
  // (a) Standalone marker within 2 words before.
  for (var k = Math.max(0, tokenIdx - 2); k < tokenIdx; k++) {
    if (markers.indexOf(tokens[k]) !== -1) return 'negated';
  }
  // (b) Attached: the hit token itself starts with a marker AND the remainder
  // contains the forbidden term.
  var tok = tokens[tokenIdx];
  for (var m = 0; m < markers.length; m++) {
    var mk = markers[m];
    if (tok.indexOf(mk) === 0 && tok.length > mk.length) {
      var rest = tok.slice(mk.length);
      if (rest.indexOf(hitTerm) !== -1) return 'negated';
    }
  }
  // Also: the hit token may carry an attached single-letter م prefix forming a
  // NEGATED verb ('متتفاوضش' = م + تتفاوض + ش). Require the trailing ش, so a
  // plain participle ('متفاوض' = one who negotiates, an order to negotiate)
  // is NOT mistaken for negation.
  if (tok.charAt(0) === 'م' && tok.charAt(tok.length - 1) === 'ش' && tok.indexOf(hitTerm) !== -1 && tok !== hitTerm) {
    return 'negated';
  }
  return null;
}

function validateInstruction(input) {
  var text = input.instruction_text || '';
  var policies = input.policies || [];
  var lexicon = buildLexicon(input.lexicon || []);
  if (!cleanText(text).trim()) return { verdict: 'pass' };

  // --- Structured bound path (bound_key + bound_value, all-or-nothing) ---
  if (input.bound_key && input.bound_value !== null && input.bound_value !== undefined) {
    var bv = input.bound_value;
    if (typeof bv === 'string' && bv.trim() !== '' && !isNaN(Number(bv))) bv = Number(bv);
    if (typeof bv !== 'number' || isNaN(bv)) {
      return { verdict: 'reject', code: 'invalid_bound', field: input.bound_key, detail: 'instruction bound_value is not numeric: ' + JSON.stringify(input.bound_value) };
    }
    var pol = policyNumber(policies, input.bound_key);
    if (pol.found && pol.malformed) {
      return { verdict: 'reject', code: 'malformed_policy', field: input.bound_key, detail: 'policy ' + input.bound_key + ' has a non-numeric value, cannot be checked' };
    }
    if (pol.found && boundFails(input.bound_key, bv, pol.value)) {
      return { verdict: 'reject', code: 'bound_exceeded', field: input.bound_key, detail: 'bound ' + bv + ' violates policy ' + input.bound_key + ' = ' + pol.value };
    }
  }

  // --- Free-text path, sentence by sentence ---
  var sentences = splitSentences(text);
  for (var si = 0; si < sentences.length; si++) {
    var sentence = sentences[si];
    var tokens = tokenize(sentence);
    var hits = findDangerHits(sentence, lexicon);
    if (!hits.length) continue;
    var covered = percentCoveredTokens(sentence, lexicon);
    var numbers = findNumbers(sentence, lexicon, covered);
    var percent = hasPercentMarker(sentence, lexicon);

    // Assign each number to its keyword: nearest danger keyword BEFORE it,
    // else nearest danger keyword AFTER it (spec wording, literal).
    var assigned = {}; // hit index -> [numbers]
    numbers.forEach(function (num) {
      var before = null, after = null;
      hits.forEach(function (h, hi) {
        if (h.tokenIdx <= num.tokenIdx && (before === null || h.tokenIdx > hits[before].tokenIdx)) before = hi;
        if (h.tokenIdx >= num.tokenIdx && (after === null || h.tokenIdx < hits[after].tokenIdx)) after = hi;
      });
      var owner = before !== null ? before : after;
      if (owner !== null) {
        assigned[owner] = assigned[owner] || [];
        assigned[owner].push(num);
      }
    });

    for (var hi = 0; hi < hits.length; hi++) {
      var hit = hits[hi];
      var ns = negationStatus(tokens, hit.tokenIdx, hit.term, lexicon);
      if (ns === 'exception') {
        return { verdict: 'reject', code: 'exception_requires_review', field: hit.concept, detail: 'exception marker after the verb in: ' + sentence };
      }
      if (ns === 'negated') continue; // tightening: this hit passes
      var owned = assigned[hi] || [];
      var key = conceptBoundKey(hit.concept);
      // Cash discount: a discount hit with a cash marker in the sentence maps
      // to cash_discount_pct instead of max_discount_pct.
      if (hit.concept === 'discount' && (sentence.indexOf('كاش') !== -1 || sentence.indexOf('نقدي') !== -1)) {
        key = 'cash_discount_pct';
      }
      if (percent && !owned.length) {
        // Slot token = the token immediately before the percent marker (if it
        // is not a digit). E.g. 'زعبلوط' in 'خصم زعبلوط في المية'.
        var coveredIdx = Object.keys(covered).map(Number).sort(function (a, b) { return a - b; });
        var slotTok = null;
        var markerIdx = coveredIdx.length ? coveredIdx[0] : -1;
        if (markerIdx === -1) {
          tokens.forEach(function (t, ti) {
            if (t.indexOf('٪') !== -1 || t.indexOf('%') !== -1) markerIdx = ti;
          });
        }
        if (markerIdx > 0 && !/^\d/.test(tokens[markerIdx - 1])) slotTok = tokens[markerIdx - 1];
        return { verdict: 'reject', code: 'unknown_number_word', field: hit.concept, detail: 'percent marker with no resolvable number' + (slotTok ? ' (slot token: ' + slotTok + ')' : '') + ' in: ' + sentence };
      }
      if (key) {
        var p2 = policyNumber(policies, key);
        if (p2.found && p2.malformed) {
          return { verdict: 'reject', code: 'malformed_policy', field: key, detail: 'policy ' + key + ' has a non-numeric value, cannot be checked' };
        }
        var detail = 'danger concept ' + hit.concept + ' in free text; use the structured field ' + key;
        if (owned.length && p2.found) {
          detail += ' (bound number ' + owned[0].value + ' vs policy ' + key + ' = ' + p2.value + ')';
        } else if (owned.length) {
          detail += ' (bound number ' + owned[0].value + ', no policy row for ' + key + ')';
        }
        return { verdict: 'reject', code: 'use_structured_field', field: key, detail: detail };
      }
      return { verdict: 'reject', code: 'forbidden_action', field: hit.concept, detail: 'forbidden action in free text: ' + hit.term + ' in: ' + sentence };
    }
  }
  return { verdict: 'pass' };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { validateInstruction: validateInstruction, cleanText: cleanText, buildLexicon: buildLexicon };
}

// ---- n8n wrapper below (not part of the tested file) ----
const row = $('Read Row').first().json;
const policiesRows = $('Read Policies').all().map((i) => i.json);
const lexiconRows = $('Read Lexicon').all().map((i) => i.json);
const result = validateInstruction({
  instruction_text: row.instruction_text,
  bound_key: row.bound_key,
  bound_value: row.bound_value,
  policies: policiesRows.map((p) => ({ key: p.policy_key, value: p.policy_value })),
  lexicon: lexiconRows.map((l) => ({ dialect: l.dialect, concept: l.concept, term: l.term, term_value: l.term_value, is_active: true }))
});
return [{ json: { instruction_id: row.id, tenant_id: row.tenant_id, instruction_updated_at: row.updated_at, verdict: result.verdict, code: result.code || null, field: result.field || null, detail: result.detail || null } }];
